    // ---------------------------------------------------------------
    // Distance short codes: when a freshly-decoded distance *symbol* is
    // in 0..16, it doesn't encode a distance directly - it references
    // one of the last 4 real distances used (a 4-slot ring buffer),
    // optionally with a small ± delta. Symbol 0 always means "the very
    // last distance used, again" (`distance_context` set to 1 in this
    // case specifically, used to pick which distance Huffman tree the
    // *next* command with this same short-code shape should use).
    // Symbols 1-15 resolve via two fixed, packed-2-bits-per-entry
    // lookup constants - `kDistanceShortCodeIndexOffset`/
    // `kDistanceShortCodeValueOffset` - ported verbatim from
    // `TakeDistanceFromRingBuffer` rather than expanded into a 16-entry
    // table by hand, since the packed form is both smaller and a
    // direct, unambiguous copy of the reference's own bit-trick (no
    // hand-transcription of 16 rows to get subtly wrong).
    // ---------------------------------------------------------------
    fn take_distance_from_ring_buffer(
        raw_code: i32,
        dist_rb: &mut [i32; 4],
        dist_rb_idx: &mut i32,
    ) -> (i32, i32) {
        if raw_code == 0 {
            *dist_rb_idx -= 1;
            let distance = dist_rb[(*dist_rb_idx & 3) as usize];
            (distance, 1)
        } else {
            const INDEX_OFFSET: u32 = 0xaaaf_ff1b;
            const VALUE_OFFSET: u32 = 0xfa5f_a500;
            // Note: `shift` (= `raw_code << 1`) is what the reference
            // calls `distance_code` in this function - confirmed
            // directly against `TakeDistanceFromRingBuffer`'s own
            // source, and load-bearing: an earlier draft checked
            // `raw_code & 0x3` here instead of `shift & 0x3`, which
            // happens to agree with the reference for most values of
            // `raw_code` but silently picks the wrong add/subtract
            // branch (and therefore the wrong resolved distance) for
            // others - found via a real decode mismatch traced back to
            // exactly this one bit, not reasoned out in advance.
            let shift = raw_code << 1;
            let v_idx = ((*dist_rb_idx + ((INDEX_OFFSET as i32) >> shift)) & 0x3) as usize;
            let mut distance = dist_rb[v_idx];
            let delta = ((VALUE_OFFSET >> shift) & 0x3) as i32;
            if (shift & 0x3) != 0 {
                distance += delta;
            } else {
                distance -= delta;
                if distance <= 0 {
                    distance = 0x7fff_ffff;
                }
            }
            (distance, 0)
        }
    }

    const NUM_DISTANCE_SHORT_CODES: u32 = 16;
    const BROTLI_MAX_DISTANCE_BITS: u32 = 24;
    const BROTLI_MAX_ALLOWED_DISTANCE: i64 = 0x7fff_fffc;

    fn distance_alphabet_size(npostfix: u32, ndirect: u32, max_nbits: u32) -> u32 {
        NUM_DISTANCE_SHORT_CODES + ndirect + (max_nbits << (npostfix + 1))
    }

    /// Decodes one real distance code (`ReadDistanceInternal`), given a
    /// freshly Huffman-decoded raw symbol. Values 0..16 resolve via the
    /// ring buffer (`take_distance_from_ring_buffer`); larger values
    /// resolve via the NDIRECT/NPOSTFIX-parameterized "direct or
    /// computed" distance encoding RFC 7932 defines - ported directly
    /// from `ReadDistanceInternal`'s own arithmetic (the `distval`/
    /// `nbits`/`offset`/`postfix` sequence), including the final
    /// `- NUM_DISTANCE_SHORT_CODES + 1` rebasing shared by every
    /// non-ring-buffer distance regardless of which of the two arms
    /// produced it.
    fn read_distance(
        br: &mut BitReader,
        raw_code: u32,
        num_direct_distance_codes: u32,
        distance_postfix_bits: u32,
        distance_postfix_mask: i32,
        dist_rb: &mut [i32; 4],
        dist_rb_idx: &mut i32,
    ) -> Result<(i32, i32)> {
        if raw_code < 16 {
            let (distance, distance_context) =
                take_distance_from_ring_buffer(raw_code as i32, dist_rb, dist_rb_idx);
            return Ok((distance, distance_context));
        }
        let mut distance_code = raw_code as i32;
        let distval = distance_code - num_direct_distance_codes as i32;
        if distval >= 0 {
            let postfix = distval & distance_postfix_mask;
            let distval_shifted = distval >> distance_postfix_bits;
            let nbits = ((distval_shifted as u32) >> 1) + 1;
            let bits = br.read(nbits)?;
            let offset = (((distval_shifted & 1) + 2) << nbits) - 4;
            distance_code = (((i64::from(offset) + i64::from(bits)) << distance_postfix_bits)
                + i64::from(postfix)
                + i64::from(num_direct_distance_codes)) as i32;
        }
        distance_code = distance_code - NUM_DISTANCE_SHORT_CODES as i32 + 1;
        Ok((distance_code, 0))
    }

    // ---------------------------------------------------------------
    // The static dictionary (RFC 7932 Appendix A) and its 121 word
    // transforms (Appendix B) - used whenever a command's own distance
    // exceeds the real, already-produced output (`max_distance`),
    // referencing one of ~13,000 common English/multi-language words
    // instead of an actual prior LZ77 match. `BROTLI_DICTIONARY` and
    // `DICT_OFFSETS_BY_LENGTH`/`DICT_SIZE_BITS_BY_LENGTH` are ported
    // verbatim (byte-for-byte extracted from `dictionary/mod.rs`'s own
    // committed source, not re-derived) - this is pure static data, the
    // same "vendor exact bytes, verify behavior against real files"
    // treatment this project already gives Excel's date-serial tables
    // and the zstd predefined FSE distributions.
    // ---------------------------------------------------------------
    const BROTLI_MIN_DICTIONARY_WORD_LENGTH: usize = 4;
    const BROTLI_MAX_DICTIONARY_WORD_LENGTH: usize = 24;
    const DICT_OFFSETS_BY_LENGTH: [u32; 25] = [
        0, 0, 0, 0, 0, 4096, 9216, 21504, 35840, 44032, 53248, 63488, 74752, 87040, 93696, 100864,
        104704, 106752, 108928, 113536, 115968, 118528, 119872, 121280, 122016,
    ];
    const DICT_SIZE_BITS_BY_LENGTH: [u8; 25] = [
        0, 0, 0, 0, 10, 10, 11, 11, 10, 10, 10, 10, 10, 9, 9, 8, 7, 7, 8, 7, 7, 6, 6, 5, 5,
    ];
    const NUM_TRANSFORMS: usize = 121;
    const TRANSFORM_OMIT_LAST_MAX: u8 = 9;
    const TRANSFORM_UPPERCASE_FIRST: u8 = 10;
    const TRANSFORM_UPPERCASE_ALL: u8 = 11;
    const TRANSFORM_OMIT_FIRST_BASE: u8 = 12;

    /// The "overly simplified" UTF-8 uppercasing Brotli's own dictionary
    /// transforms use (the reference's own comment, verbatim) - ported
    /// exactly rather than replaced with real Unicode casing, since the
    /// dictionary word bytes this operates on are fixed, known static
    /// data and a real encoder only ever relies on this specific
    /// (non-general-purpose) transform when producing a matching
    /// stream. Returns how many bytes of `p` this call consumed.
    fn brotli_to_upper_case(p: &mut [u8]) -> usize {
        if p[0] < 0xc0 {
            if p[0].is_ascii_lowercase() {
                p[0] ^= 32;
            }
            1
        } else if p[0] < 0xe0 {
            p[1] ^= 32;
            2
        } else {
            p[2] ^= 5;
            3
        }
    }

    /// Applies one of the 121 dictionary-word transforms
    /// (`TransformDictionaryWord`): a fixed prefix string, then the
    /// word itself with `skip` bytes trimmed from the front (only for
    /// `OmitFirst1..9`) and/or `t` bytes trimmed from the back (only
    /// for `OmitLast1..9`, `t` itself being the trim count) with an
    /// optional uppercase pass over the surviving bytes, then a fixed
    /// suffix string - both fixed strings are NUL-terminated substrings
    /// of the 208-byte `TRANSFORM_PREFIX_SUFFIX` blob, addressed by a
    /// byte offset baked into `TRANSFORMS` itself. Returns the total
    /// number of bytes written to `dst`.
    fn apply_transform(dst: &mut [u8], word: &[u8], transform_idx: usize) -> usize {
        let (prefix_id, t, suffix_id) = TRANSFORMS[transform_idx];
        let mut idx = 0usize;
        let mut p = prefix_id as usize;
        while TRANSFORM_PREFIX_SUFFIX[p] != 0 {
            dst[idx] = TRANSFORM_PREFIX_SUFFIX[p];
            idx += 1;
            p += 1;
        }
        let mut skip = if t < TRANSFORM_OMIT_FIRST_BASE {
            0
        } else {
            (t - (TRANSFORM_OMIT_FIRST_BASE - 1)) as usize
        };
        let mut len = word.len();
        if skip > len {
            skip = len;
        }
        let mut word = &word[skip..];
        len -= skip;
        if t <= TRANSFORM_OMIT_LAST_MAX {
            len -= usize::from(t);
        }
        word = &word[..len];
        let word_start = idx;
        dst[idx..idx + len].copy_from_slice(word);
        idx += len;
        if t == TRANSFORM_UPPERCASE_FIRST {
            if len > 0 {
                brotli_to_upper_case(&mut dst[word_start..idx]);
            }
        } else if t == TRANSFORM_UPPERCASE_ALL {
            let mut offset = word_start;
            while offset < idx {
                offset += brotli_to_upper_case(&mut dst[offset..idx]);
            }
        }
        let mut s = suffix_id as usize;
        while TRANSFORM_PREFIX_SUFFIX[s] != 0 {
            dst[idx] = TRANSFORM_PREFIX_SUFFIX[s];
            idx += 1;
            s += 1;
        }
        idx
    }

