// --- SQLite reader (opt-in via --features sqlite) ---
// A single file can hold multiple tables, so this returns one profile list
// per table rather than a flat column list. SQLite's dynamic typing means a
// column declared INTEGER can still hold TEXT rows (a real, well-known
// SQLite quirk) - Current Type is built from what's actually stored per
// value, not the declared column type, so that quirk surfaces as a "mixed"
// type exactly like an inconsistent JSON field would.

#[cfg(feature = "sqlite")]
#[derive(PartialEq, Eq, Clone, Copy)]
enum SqlKind {
    Integer = 0,
    Real = 1,
    Text = 2,
    Blob = 3,
}

/// Every `SqlKind` variant, in discriminant order - mirrors
/// `ALL_JSON_KINDS`/`JsonKindCounts` (see that pair's own doc comment
/// for the profiler finding both are built for): a per-value storage-
/// class tally, incremented once per value of every column of every
/// SQLite table this tool reads, is exactly the same shape of hot loop
/// that made a `HashMap<JsonKind, usize>` worth replacing with a plain
/// array there - SQLite's own storage classes are an equally small,
/// fixed, closed set, so the identical fix applies here too.
#[cfg(feature = "sqlite")]
const ALL_SQL_KINDS: [SqlKind; 4] = [
    SqlKind::Integer,
    SqlKind::Real,
    SqlKind::Text,
    SqlKind::Blob,
];

#[cfg(feature = "sqlite")]
fn sql_kind_label(k: SqlKind) -> &'static str {
    match k {
        SqlKind::Integer => "i64",
        SqlKind::Real => "f64",
        SqlKind::Text => "String",
        SqlKind::Blob => "Blob",
    }
}

#[cfg(feature = "sqlite")]
#[derive(Default, Clone, Copy)]
struct SqlKindCounts([usize; 4]);

#[cfg(feature = "sqlite")]
impl SqlKindCounts {
    fn increment(&mut self, k: SqlKind) {
        self.0[k as usize] += 1;
    }

    fn is_empty(&self) -> bool {
        self.0.iter().all(|&c| c == 0)
    }

    fn observed(&self) -> impl Iterator<Item = (SqlKind, usize)> + '_ {
        ALL_SQL_KINDS
            .into_iter()
            .zip(self.0)
            .filter(|(_, c)| *c > 0)
    }
}

#[cfg(feature = "sqlite")]
fn describe_sql_kinds(counts: &SqlKindCounts) -> String {
    let mut observed = counts.observed();
    let Some(first) = observed.next() else {
        return String::new();
    };
    let Some(second) = observed.next() else {
        return sql_kind_label(first.0).to_string();
    };
    let mut parts: Vec<(String, usize)> = std::iter::once(first)
        .chain(std::iter::once(second))
        .chain(observed)
        .map(|(k, c)| (sql_kind_label(k).to_string(), c))
        .collect();
    parts.sort_by(|a, b| a.0.cmp(&b.0));
    let inner = parts
        .iter()
        .map(|(label, count)| format!("{label}: {count}"))
        .collect::<Vec<_>>()
        .join(", ");
    format!("mixed({inner})")
}

#[cfg(feature = "sqlite")]
mod sqlite_support {
    use super::*;
    use std::io::{Read, Seek, SeekFrom};

    /// SQLite's own on-disk B-tree/record format, hand-decoded directly
    /// from the file bytes. `rusqlite` couldn't play the same "read the
    /// crate's own source" role every other hand-roll in this project
    /// leaned on - it's a thin FFI binding over the real, linked SQLite C
    /// library, not a Rust reimplementation of the file format, so the
    /// authoritative source here is SQLite's own published file-format
    /// specification (sqlite.org/fileformat2.html) rather than any
    /// crate's source tree.
    ///
    /// Scope is deliberately narrow, matching exactly what this project's
    /// prior rusqlite-based reader ever actually asked SQLite to do: list
    /// user tables from `sqlite_master`, then an unfiltered, unordered
    /// full table scan (`SELECT * FROM t`) per table - no WHERE/JOIN/
    /// aggregation/index lookups of any kind, so only the table b-tree
    /// (never an index b-tree) ever needs walking, and rowid-ascending
    /// depth-first traversal order (the b-tree's own natural cell order)
    /// is exactly what a real, index-free `SELECT *` returns too.
    const MAX_BTREE_DEPTH: u32 = 64;
    const MAX_OVERFLOW_PAGES: u32 = 10_000_000;
    const MAX_ROW_PAYLOAD: i64 = 1024 * 1024 * 1024;

    struct DbHeader {
        page_size: u32,
        usable_size: u32,
        text_encoding: u32,
    }

    #[derive(Debug, Clone)]
    enum Value {
        Null,
        Integer(i64),
        Real(f64),
        Text(String),
        Blob(usize), // length only - all this reader ever renders is "<blob: N bytes>"
    }

    fn value_to_string(value: &Value, kind_counts: &mut SqlKindCounts) -> Option<String> {
        match value {
            Value::Null => None,
            Value::Integer(n) => {
                kind_counts.increment(SqlKind::Integer);
                Some(n.to_string())
            }
            Value::Real(f) => {
                kind_counts.increment(SqlKind::Real);
                Some(f.to_string())
            }
            Value::Text(s) => {
                kind_counts.increment(SqlKind::Text);
                Some(s.clone())
            }
            Value::Blob(len) => {
                kind_counts.increment(SqlKind::Blob);
                Some(format!("<blob: {len} bytes>"))
            }
        }
    }

    /// SQLite's own write-ahead log holds committed changes not yet
    /// merged back into the base file - the real SQLite C library
    /// reconciles it transparently on every open, which this hand-rolled
    /// reader deliberately does not reimplement. Rather than silently
    /// serve stale data (a real, disclosed scope boundary, not a silent
    /// gap - the same "clean error over a wrong answer" choice every
    /// other hand-roll in this project makes for its own out-of-scope
    /// corner), a WAL file carrying more than just its own 32-byte header
    /// (i.e. at least one real frame) is a hard, actionable error.
    fn check_no_pending_wal(path: &Path) -> Result<()> {
        let mut wal_name = path.as_os_str().to_os_string();
        wal_name.push("-wal");
        let wal_path = PathBuf::from(wal_name);
        if let Ok(meta) = fs::metadata(&wal_path)
            && meta.len() > 32
        {
            bail!(
                "{path:?} has a write-ahead log ({wal_path:?}) with pending, uncheckpointed \
                 changes - run `PRAGMA wal_checkpoint(TRUNCATE);` (or close every connection \
                 cleanly) before reading it with this tool"
            );
        }
        Ok(())
    }

    fn read_header(data: &[u8], path: &Path) -> Result<DbHeader> {
        if data.len() < 100 || &data[0..16] != b"SQLite format 3\0" {
            bail!("{path:?} does not start with the SQLite file-format magic string");
        }
        let page_size_raw = u16::from_be_bytes([data[16], data[17]]);
        let page_size: u32 = if page_size_raw == 1 {
            65536
        } else {
            page_size_raw as u32
        };
        if page_size < 512 || (page_size & (page_size - 1)) != 0 {
            bail!("{path:?} declares an invalid SQLite page size ({page_size})");
        }
        let reserved = data[20] as u32;
        let usable_size = page_size.saturating_sub(reserved);
        if usable_size < 480 {
            bail!("{path:?} declares an invalid SQLite usable page size ({usable_size})");
        }
        let text_encoding = u32::from_be_bytes(data[56..60].try_into().unwrap());
        Ok(DbHeader {
            page_size,
            usable_size,
            text_encoding,
        })
    }

    /// SQLite's own variable-length integer: up to 9 big-endian bytes,
    /// the first 8 contributing 7 bits each behind a high continuation
    /// bit, the 9th (if reached) contributing a full 8 bits with no
    /// continuation bit of its own - verified directly against
    /// sqlite.org's own file-format documentation.
    fn read_varint(data: &[u8], offset: usize) -> Result<(i64, usize)> {
        let mut result: i64 = 0;
        for i in 0..8 {
            let byte = *data.get(offset + i).context("truncated SQLite varint")?;
            result = (result << 7) | (byte & 0x7f) as i64;
            if byte & 0x80 == 0 {
                return Ok((result, i + 1));
            }
        }
        let byte = *data.get(offset + 8).context("truncated SQLite varint")?;
        result = (result << 8) | byte as i64;
        Ok((result, 9))
    }

    /// Reads exactly one page fresh off disk via `Seek`, instead of
    /// slicing into a whole-file buffer - the change that lets this
    /// reader's own peak memory scale with page size rather than with
    /// database size. A b-tree walk only ever needs one page (or, during
    /// an overflow chain, one page plus whatever's already been
    /// assembled for that single row) resident at a time regardless of
    /// how large the table or file is - unlike a plain sequential
    /// format, SQLite's own page-graph structure already makes random
    /// access to individual pages the *natural* access pattern, not an
    /// added complication a streaming rewrite has to invent from
    /// scratch.
    fn read_page(
        file: &mut fs::File,
        page_num: u32,
        page_size: u32,
        path: &Path,
    ) -> Result<Vec<u8>> {
        if page_num == 0 {
            bail!("invalid SQLite page number 0 in {path:?}");
        }
        let offset = (page_num as u64 - 1) * page_size as u64;
        file.seek(SeekFrom::Start(offset))
            .with_context(|| format!("failed seeking to SQLite page {page_num} in {path:?}"))?;
        let mut buf = vec![0u8; page_size as usize];
        file.read_exact(&mut buf).with_context(|| {
            format!(
                "SQLite page {page_num} is out of range in {path:?} (file truncated or corrupt)"
            )
        })?;
        Ok(buf)
    }

    /// Walks a table b-tree (rowid table only - an index b-tree page type
    /// here means the table uses WITHOUT ROWID storage, a disclosed,
    /// unsupported shape) depth-first, invoking `on_row` for every leaf
    /// row's `(rowid, payload)` in ascending-rowid order - exactly the
    /// order an index-free `SELECT *` returns rows in. Calling back per
    /// row instead of collecting into a `Vec` first is what lets a full
    /// table scan build its column accumulators incrementally, the same
    /// "fold each record straight into per-column storage" shape
    /// `CsvColumnAccumulator` already uses for CSV - the b-tree walk
    /// itself never needs to hold more than one row's own decoded
    /// payload at a time.
    #[allow(clippy::too_many_arguments)]
    fn collect_table_rows(
        file: &mut fs::File,
        page_num: u32,
        page_size: u32,
        usable_size: u32,
        path: &Path,
        depth: u32,
        limit: Option<usize>,
        count: &mut usize,
        on_row: &mut dyn FnMut(i64, Vec<u8>) -> Result<()>,
    ) -> Result<()> {
        if limit.is_some_and(|n| *count >= n) {
            return Ok(());
        }
        if depth > MAX_BTREE_DEPTH {
            bail!(
                "SQLite b-tree in {path:?} is nested past {MAX_BTREE_DEPTH} levels (likely a corrupt page-number cycle)"
            );
        }
        let page = read_page(file, page_num, page_size, path)?;
        let hdr_off = if page_num == 1 { 100 } else { 0 };
        let page_type = *page.get(hdr_off).context("truncated SQLite page header")?;
        let num_cells = u16::from_be_bytes([
            *page
                .get(hdr_off + 3)
                .context("truncated SQLite page header")?,
            *page
                .get(hdr_off + 4)
                .context("truncated SQLite page header")?,
        ]) as usize;
        let (is_interior, header_len) = match page_type {
            0x0d => (false, 8),
            0x05 => (true, 12),
            0x0a | 0x02 => bail!(
                "page {page_num} in {path:?} is an index b-tree page - WITHOUT ROWID tables aren't supported"
            ),
            other => bail!(
                "unrecognized SQLite b-tree page type {other:#04x} at page {page_num} in {path:?}"
            ),
        };
        let cell_ptr_base = hdr_off + header_len;
        for i in 0..num_cells {
            if limit.is_some_and(|n| *count >= n) {
                return Ok(());
            }
            let ptr_off = cell_ptr_base + i * 2;
            let cell_off = u16::from_be_bytes([
                *page
                    .get(ptr_off)
                    .context("truncated SQLite cell pointer array")?,
                *page
                    .get(ptr_off + 1)
                    .context("truncated SQLite cell pointer array")?,
            ]) as usize;
            if is_interior {
                let child = u32::from_be_bytes(
                    page.get(cell_off..cell_off + 4)
                        .context("truncated SQLite interior cell")?
                        .try_into()
                        .unwrap(),
                );
                collect_table_rows(
                    file,
                    child,
                    page_size,
                    usable_size,
                    path,
                    depth + 1,
                    limit,
                    count,
                    on_row,
                )?;
            } else {
                let (rowid, payload) =
                    parse_leaf_cell(file, &page, cell_off, page_size, usable_size, path)?;
                on_row(rowid, payload)?;
                *count += 1;
            }
        }
        if is_interior && limit.is_none_or(|n| *count < n) {
            let rightmost = u32::from_be_bytes(
                page.get(hdr_off + 8..hdr_off + 12)
                    .context("truncated SQLite interior page header")?
                    .try_into()
                    .unwrap(),
            );
            collect_table_rows(
                file,
                rightmost,
                page_size,
                usable_size,
                path,
                depth + 1,
                limit,
                count,
                on_row,
            )?;
        }
        Ok(())
    }

    /// Table b-tree leaf cell: varint payload size, varint rowid, the
    /// initial payload bytes, and - only when the payload is too large to
    /// fit locally - a trailing 4-byte pointer to a linked list of
    /// overflow pages. The `X`/`M`/`K` formulas are sqlite.org's own,
    /// verified directly against its file-format documentation rather
    /// than recalled from memory.
    fn parse_leaf_cell(
        file: &mut fs::File,
        page: &[u8],
        cell_off: usize,
        page_size: u32,
        usable_size: u32,
        path: &Path,
    ) -> Result<(i64, Vec<u8>)> {
        let (payload_size, n1) =
            read_varint(page, cell_off).context("truncated SQLite leaf cell")?;
        let (rowid, n2) = read_varint(page, cell_off + n1).context("truncated SQLite leaf cell")?;
        if !(0..=MAX_ROW_PAYLOAD).contains(&payload_size) {
            bail!("SQLite row payload size {payload_size} in {path:?} is out of a sane range");
        }
        let body_off = cell_off + n1 + n2;
        let usable = usable_size as i64;
        let x = usable - 35;
        let payload = if payload_size <= x {
            let end = body_off
                .checked_add(payload_size as usize)
                .context("SQLite leaf cell payload length overflow")?;
            page.get(body_off..end)
                .context("truncated SQLite leaf cell payload")?
                .to_vec()
        } else {
            let m = ((usable - 12) * 32 / 255) - 23;
            let k = m + ((payload_size - m) % (usable - 4));
            let local_size = (if k <= x { k } else { m }) as usize;
            let local_end = body_off
                .checked_add(local_size)
                .context("SQLite leaf cell local payload length overflow")?;
            let mut buf = page
                .get(body_off..local_end)
                .context("truncated SQLite leaf cell local payload")?
                .to_vec();
            let overflow_off = local_end;
            let mut next_page = u32::from_be_bytes(
                page.get(overflow_off..overflow_off + 4)
                    .context("truncated SQLite overflow page pointer")?
                    .try_into()
                    .unwrap(),
            );
            let mut remaining = payload_size - local_size as i64;
            let mut guard = 0u32;
            while next_page != 0 && remaining > 0 {
                guard += 1;
                if guard > MAX_OVERFLOW_PAGES {
                    bail!(
                        "SQLite overflow chain in {path:?} is unreasonably long (possibly corrupt or cyclic)"
                    );
                }
                let opage = read_page(file, next_page, page_size, path)?;
                let follow = u32::from_be_bytes(opage[0..4].try_into().unwrap());
                let capacity = usable - 4;
                let take = remaining.min(capacity) as usize;
                buf.extend_from_slice(
                    opage
                        .get(4..4 + take)
                        .context("truncated SQLite overflow page")?,
                );
                remaining -= take as i64;
                next_page = follow;
            }
            if remaining > 0 {
                bail!("SQLite overflow chain in {path:?} ended before the full payload was read");
            }
            buf
        };
        Ok((rowid, payload))
    }

    /// SQLite's own record format: a varint-prefixed header of one
    /// serial-type varint per column, followed by the values themselves
    /// in the same order. Serial type codes verified directly against
    /// sqlite.org's own file-format documentation.
    fn decode_record(payload: &[u8]) -> Result<Vec<Value>> {
        let (header_len, n) = read_varint(payload, 0).context("truncated SQLite record header")?;
        if header_len < n as i64 {
            bail!("SQLite record header length is smaller than its own varint");
        }
        let header_end = header_len as usize;
        let mut off = n;
        let mut serial_types = Vec::new();
        while off < header_end {
            let (st, sn) = read_varint(payload, off).context("truncated SQLite record header")?;
            serial_types.push(st);
            off += sn;
        }
        let mut body_off = header_end;
        let mut values = Vec::with_capacity(serial_types.len());
        for st in serial_types {
            let (value, size) = decode_serial(payload, body_off, st)?;
            values.push(value);
            body_off += size;
        }
        Ok(values)
    }

    fn decode_serial(payload: &[u8], off: usize, serial_type: i64) -> Result<(Value, usize)> {
        Ok(match serial_type {
            0 => (Value::Null, 0),
            1 => (
                Value::Integer(
                    *payload.get(off).context("truncated SQLite record value")? as i8 as i64,
                ),
                1,
            ),
            2 => {
                let b = payload
                    .get(off..off + 2)
                    .context("truncated SQLite record value")?;
                (
                    Value::Integer(i16::from_be_bytes(b.try_into().unwrap()) as i64),
                    2,
                )
            }
            3 => {
                let b = payload
                    .get(off..off + 3)
                    .context("truncated SQLite record value")?;
                let mut v = ((b[0] as i32) << 16) | ((b[1] as i32) << 8) | (b[2] as i32);
                if b[0] & 0x80 != 0 {
                    v -= 1 << 24;
                }
                (Value::Integer(v as i64), 3)
            }
            4 => {
                let b = payload
                    .get(off..off + 4)
                    .context("truncated SQLite record value")?;
                (
                    Value::Integer(i32::from_be_bytes(b.try_into().unwrap()) as i64),
                    4,
                )
            }
            5 => {
                let b = payload
                    .get(off..off + 6)
                    .context("truncated SQLite record value")?;
                let mut buf = [0u8; 8];
                buf[2..8].copy_from_slice(b);
                let mut v = i64::from_be_bytes(buf);
                if b[0] & 0x80 != 0 {
                    v -= 1 << 48;
                }
                (Value::Integer(v), 6)
            }
            6 => {
                let b = payload
                    .get(off..off + 8)
                    .context("truncated SQLite record value")?;
                (Value::Integer(i64::from_be_bytes(b.try_into().unwrap())), 8)
            }
            7 => {
                let b = payload
                    .get(off..off + 8)
                    .context("truncated SQLite record value")?;
                (Value::Real(f64::from_be_bytes(b.try_into().unwrap())), 8)
            }
            8 => (Value::Integer(0), 0),
            9 => (Value::Integer(1), 0),
            10 | 11 => bail!("SQLite record uses reserved serial type {serial_type}"),
            n if n >= 12 => {
                if n % 2 == 0 {
                    let len = ((n - 12) / 2) as usize;
                    (Value::Blob(len), len)
                } else {
                    let len = ((n - 13) / 2) as usize;
                    let end = off
                        .checked_add(len)
                        .context("SQLite record text length overflow")?;
                    let bytes = payload
                        .get(off..end)
                        .context("truncated SQLite record text value")?;
                    let text = String::from_utf8(bytes.to_vec())
                        .map_err(|_| anyhow!("SQLite TEXT value is not valid UTF-8"))?;
                    (Value::Text(text), len)
                }
            }
            other => bail!("negative or invalid SQLite serial type {other}"),
        })
    }

    struct SchemaEntry {
        name: String,
        rootpage: u32,
        sql: String,
    }

    /// `sqlite_master`'s root page is always page 1 by construction - one
    /// more fixed fact of the file format, not something to look up.
    fn read_schema(
        file: &mut fs::File,
        header: &DbHeader,
        path: &Path,
    ) -> Result<Vec<SchemaEntry>> {
        let mut entries = Vec::new();
        let mut count = 0usize;
        let mut on_row = |_rowid: i64, payload: Vec<u8>| -> Result<()> {
            let values = decode_record(&payload)
                .with_context(|| format!("failed decoding a sqlite_master row in {path:?}"))?;
            if values.len() < 5 {
                return Ok(());
            }
            let Value::Text(kind) = &values[0] else {
                return Ok(());
            };
            if kind != "table" {
                return Ok(());
            }
            let Value::Text(name) = &values[1] else {
                return Ok(());
            };
            // Mirrors `NOT LIKE 'sqlite_%'`, which SQLite's own LIKE
            // operator evaluates case-insensitively for ASCII.
            if name.to_ascii_lowercase().starts_with("sqlite_") {
                return Ok(());
            }
            let Value::Integer(rootpage) = &values[3] else {
                return Ok(());
            };
            if *rootpage <= 0 {
                return Ok(());
            }
            let sql = match &values[4] {
                Value::Text(s) => s.clone(),
                _ => String::new(),
            };
            entries.push(SchemaEntry {
                name: name.clone(),
                rootpage: *rootpage as u32,
                sql,
            });
            Ok(())
        };
        collect_table_rows(
            file,
            1,
            header.page_size,
            header.usable_size,
            path,
            0,
            None,
            &mut count,
            &mut on_row,
        )
        .with_context(|| format!("failed reading the SQLite schema (sqlite_master) in {path:?}"))?;

        entries.sort_by(|a, b| a.name.cmp(&b.name));
        Ok(entries)
    }

    struct ParsedTable {
        columns: Vec<String>,
        rowid_alias_index: Option<usize>,
        without_rowid: bool,
        // Whether each column's declared type resolves to REAL affinity -
        // the one affinity that needs special handling on *read*, not
        // just at write time (see `apply_affinity`).
        real_affinity: Vec<bool>,
    }

    fn contains_word(haystack: &str, word: &str) -> bool {
        haystack
            .split(|c: char| !c.is_alphanumeric() && c != '_')
            .any(|w| w == word)
    }

    /// SQLite's own "Determination Of Column Affinity" algorithm
    /// (sqlite.org/datatype3.html), five substring rules checked in
    /// order - verified directly against that page's exact wording
    /// rather than recalled from memory, since a real oracle-comparison
    /// mismatch on `sample.sqlite`'s `amount REAL` column (a whole-number
    /// value silently stored on disk as an integer, then read back as a
    /// float - see the sibling `apply_affinity` doc comment) is exactly
    /// what surfaced the need for this in the first place.
    fn column_affinity_is_real(type_name: &str) -> bool {
        let t = type_name.to_ascii_uppercase();
        let is_integer = t.contains("INT");
        let is_text = t.contains("CHAR") || t.contains("CLOB") || t.contains("TEXT");
        let is_blob = t.contains("BLOB") || t.trim().is_empty();
        !is_integer
            && !is_text
            && !is_blob
            && (t.contains("REAL") || t.contains("FLOA") || t.contains("DOUB"))
    }

    /// A REAL-affinity column's whole-number values are, per sqlite.org's
    /// own documented internal optimization, "written to disk as integers
    /// in order to take up less space and are automatically converted
    /// back into floating point as the value is read out. This
    /// optimization is completely invisible at the SQL level and can
    /// only be detected by examining the raw bits of the database file" -
    /// exactly the raw bits this hand-rolled reader examines directly,
    /// so it has to replicate the read-time conversion `rusqlite`/the
    /// real SQLite C library apply, or it reports a storage-class detail
    /// no query against the same file would ever actually see. No other
    /// affinity gets an equivalent read-time rewrite (NUMERIC affinity
    /// may use the same integer-storage optimization for a whole-number
    /// float, but - unlike REAL affinity - is *not* documented to convert
    /// it back on read, a well-known asymmetry).
    fn apply_affinity(value: Value, is_real_affinity: bool) -> Value {
        match value {
            Value::Integer(n) if is_real_affinity => Value::Real(n as f64),
            other => other,
        }
    }

    const COLUMN_CONSTRAINT_KEYWORDS: &[&str] = &[
        "primary",
        "not",
        "null",
        "default",
        "unique",
        "check",
        "references",
        "collate",
        "generated",
        "as",
        "constraint",
    ];

    /// Finds where a column's declared-type text ends and its own
    /// constraints begin, by locating the first whole-word match (case-
    /// insensitive) of a real column-constraint keyword - needed because
    /// a declared type can be multiple words (`DOUBLE PRECISION`,
    /// `UNSIGNED BIG INT`), so affinity has to be computed over the whole
    /// span, not just the first token.
    fn first_keyword_boundary(s: &[char], start: usize, end: usize, keywords: &[&str]) -> usize {
        let mut i = start;
        while i < end {
            if s[i].is_alphanumeric() || s[i] == '_' {
                let word_start = i;
                while i < end && (s[i].is_alphanumeric() || s[i] == '_') {
                    i += 1;
                }
                let word: String = s[word_start..i]
                    .iter()
                    .collect::<String>()
                    .to_ascii_lowercase();
                if keywords.contains(&word.as_str()) {
                    return word_start;
                }
            } else {
                i += 1;
            }
        }
        end
    }

    /// Replaces `-- line` and `/* block */` comments with a single space
    /// each, leaving everything else - including quoted strings and
    /// identifiers, verbatim - untouched. Quote-aware so a literal `--`
    /// or `/*` inside a string default (`DEFAULT '--not a comment'`)
    /// isn't mistaken for a real comment.
    fn strip_comments(s: &str) -> String {
        let chars: Vec<char> = s.chars().collect();
        let mut out = String::with_capacity(s.len());
        let mut i = 0;
        while i < chars.len() {
            match chars[i] {
                '\'' | '"' | '`' => {
                    let quote = chars[i];
                    out.push(quote);
                    i += 1;
                    while i < chars.len() {
                        out.push(chars[i]);
                        if chars[i] == quote {
                            if chars.get(i + 1) == Some(&quote) {
                                out.push(chars[i + 1]);
                                i += 2;
                                continue;
                            }
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                }
                '[' => {
                    out.push('[');
                    i += 1;
                    while i < chars.len() {
                        out.push(chars[i]);
                        let end = chars[i] == ']';
                        i += 1;
                        if end {
                            break;
                        }
                    }
                }
                '-' if chars.get(i + 1) == Some(&'-') => {
                    i += 2;
                    while i < chars.len() && chars[i] != '\n' {
                        i += 1;
                    }
                    out.push(' ');
                }
                '/' if chars.get(i + 1) == Some(&'*') => {
                    i += 2;
                    while i < chars.len() && !(chars[i] == '*' && chars.get(i + 1) == Some(&'/')) {
                        i += 1;
                    }
                    i = (i + 2).min(chars.len());
                    out.push(' ');
                }
                c => {
                    out.push(c);
                    i += 1;
                }
            }
        }
        out
    }

    fn find_first_top_level_char(s: &[char], target: char) -> Option<usize> {
        let mut i = 0;
        while i < s.len() {
            match s[i] {
                '\'' | '"' | '`' => {
                    let quote = s[i];
                    i += 1;
                    while i < s.len() {
                        if s[i] == quote {
                            if s.get(i + 1) == Some(&quote) {
                                i += 2;
                                continue;
                            }
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                    continue;
                }
                '[' => {
                    i += 1;
                    while i < s.len() && s[i] != ']' {
                        i += 1;
                    }
                    i += 1;
                    continue;
                }
                c if c == target => return Some(i),
                _ => {}
            }
            i += 1;
        }
        None
    }

    fn find_matching_paren(s: &[char], open_idx: usize) -> Option<usize> {
        let mut depth = 0i32;
        let mut i = open_idx;
        while i < s.len() {
            match s[i] {
                '\'' | '"' | '`' => {
                    let quote = s[i];
                    i += 1;
                    while i < s.len() {
                        if s[i] == quote {
                            if s.get(i + 1) == Some(&quote) {
                                i += 2;
                                continue;
                            }
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                    continue;
                }
                '[' => {
                    i += 1;
                    while i < s.len() && s[i] != ']' {
                        i += 1;
                    }
                    i += 1;
                    continue;
                }
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(i);
                    }
                }
                _ => {}
            }
            i += 1;
        }
        None
    }

    fn split_top_level_commas(s: &[char], start: usize, end: usize) -> Vec<(usize, usize)> {
        let mut items = Vec::new();
        let mut depth = 0i32;
        let mut item_start = start;
        let mut i = start;
        while i < end {
            match s[i] {
                '\'' | '"' | '`' => {
                    let quote = s[i];
                    i += 1;
                    while i < end {
                        if s[i] == quote {
                            if s.get(i + 1) == Some(&quote) {
                                i += 2;
                                continue;
                            }
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                    continue;
                }
                '[' => {
                    i += 1;
                    while i < end && s[i] != ']' {
                        i += 1;
                    }
                    i += 1;
                    continue;
                }
                '(' => depth += 1,
                ')' => depth -= 1,
                ',' if depth == 0 => {
                    items.push((item_start, i));
                    item_start = i + 1;
                }
                _ => {}
            }
            i += 1;
        }
        items.push((item_start, end));
        items
    }

    /// Reads one identifier (quoted via `"..."`/`` `...` ``/`'...'`/`[...]`,
    /// or a bare word) starting at the first non-whitespace character in
    /// `[start, end)`. Returns the identifier text and the index right
    /// after it.
    fn extract_identifier(s: &[char], start: usize, end: usize) -> Option<(String, usize)> {
        let mut i = start;
        while i < end && s[i].is_whitespace() {
            i += 1;
        }
        if i >= end {
            return None;
        }
        match s[i] {
            '"' | '`' | '\'' => {
                let quote = s[i];
                i += 1;
                let mut name = String::new();
                while i < end {
                    if s[i] == quote {
                        if s.get(i + 1) == Some(&quote) {
                            name.push(quote);
                            i += 2;
                            continue;
                        }
                        i += 1;
                        break;
                    }
                    name.push(s[i]);
                    i += 1;
                }
                Some((name, i))
            }
            '[' => {
                i += 1;
                let mut name = String::new();
                while i < end && s[i] != ']' {
                    name.push(s[i]);
                    i += 1;
                }
                i += 1;
                Some((name, i))
            }
            c if c.is_alphabetic() || c == '_' => {
                let word_start = i;
                while i < end && (s[i].is_alphanumeric() || s[i] == '_' || s[i] == '$') {
                    i += 1;
                }
                Some((s[word_start..i].iter().collect(), i))
            }
            _ => None,
        }
    }

    /// Extracts column names (in declared order) and detects the two
    /// things `SELECT *` needs beyond raw record decoding: a rowid-alias
    /// `INTEGER PRIMARY KEY` column (whose serial type is always 0/NULL
    /// in the record itself - the true value lives in the cell's own
    /// rowid varint instead) and `WITHOUT ROWID` storage (a disclosed,
    /// unsupported table shape - see the module doc comment). This is
    /// deliberately not a general SQL parser: just enough tokenizing
    /// (quotes, comments, paren depth) to correctly segment column
    /// definitions from table-level constraint clauses, the same "just
    /// enough, not a general evaluator" scope every other small hand-
    /// rolled parser in this project keeps.
    fn parse_create_table(sql: &str) -> Result<ParsedTable> {
        let cleaned = strip_comments(sql);
        let chars: Vec<char> = cleaned.chars().collect();

        let open = find_first_top_level_char(&chars, '(')
            .context("no column-definition list found (expected `CREATE TABLE ... (...)`)")?;
        let close = find_matching_paren(&chars, open)
            .context("unbalanced parentheses in CREATE TABLE column list")?;

        let tail: String = chars[close + 1..].iter().collect();
        let tail_lower = tail.to_ascii_lowercase();
        let without_rowid =
            contains_word(&tail_lower, "without") && contains_word(&tail_lower, "rowid");

        let items = split_top_level_commas(&chars, open + 1, close);
        let mut columns = Vec::new();
        let mut col_types_are_integer = Vec::new();
        let mut real_affinity = Vec::new();
        let mut inline_rowid_alias = None;
        let mut pk_constraint_text: Option<String> = None;

        for (item_start, item_end) in items {
            let text: String = chars[item_start..item_end].iter().collect();
            if text.trim().is_empty() {
                continue;
            }
            let lower = text.trim_start().to_ascii_lowercase();
            let is_table_constraint = lower.starts_with("primary")
                || lower.starts_with("foreign")
                || lower.starts_with("unique")
                || lower.starts_with("check")
                || lower.starts_with("constraint");
            if is_table_constraint {
                if contains_word(&lower, "primary") && contains_word(&lower, "key") {
                    pk_constraint_text = Some(text);
                }
                continue;
            }

            let (name, after) = extract_identifier(&chars, item_start, item_end)
                .context("could not find a column name in a CREATE TABLE column definition")?;
            let rest: String = chars[after..item_end].iter().collect();
            let rest_lower = rest.to_ascii_lowercase();
            let trimmed_rest = rest_lower.trim_start();
            let type_end =
                first_keyword_boundary(&chars, after, item_end, COLUMN_CONSTRAINT_KEYWORDS);
            let type_name: String = chars[after..type_end].iter().collect();
            real_affinity.push(column_affinity_is_real(&type_name));
            // Only the literal type name "INTEGER" (case-insensitively)
            // triggers rowid-aliasing - other integer-affinity spellings
            // like "INT"/"BIGINT" deliberately do not, matching SQLite's
            // own documented, easy-to-miss exact-spelling rule.
            let type_is_integer = trimmed_rest.starts_with("integer")
                && trimmed_rest[7..]
                    .chars()
                    .next()
                    .is_none_or(|c| !c.is_alphanumeric() && c != '_');
            if type_is_integer
                && contains_word(&rest_lower, "primary")
                && contains_word(&rest_lower, "key")
                && inline_rowid_alias.is_none()
            {
                let after_primary = rest_lower
                    .find("primary")
                    .map(|p| p + "primary".len())
                    .unwrap_or(0);
                if !contains_word(&rest_lower[after_primary..], "desc") {
                    inline_rowid_alias = Some(columns.len());
                }
            }
            col_types_are_integer.push(type_is_integer);
            columns.push(name);
        }

        if columns.is_empty() {
            bail!("no column definitions found");
        }

        let mut rowid_alias_index = inline_rowid_alias;
        if rowid_alias_index.is_none()
            && !without_rowid
            && let Some(pk_text) = &pk_constraint_text
        {
            let pk_lower = pk_text.to_ascii_lowercase();
            if !contains_word(&pk_lower, "desc")
                && let (Some(op), Some(cl)) = (pk_text.find('('), pk_text.rfind(')'))
            {
                let inner = &pk_text[op + 1..cl];
                let names: Vec<&str> = inner
                    .split(',')
                    .map(|s| {
                        s.trim().trim_matches(|c| {
                            c == '"' || c == '`' || c == '[' || c == ']' || c == '\''
                        })
                    })
                    .collect();
                if names.len() == 1
                    && let Some(idx) = columns
                        .iter()
                        .position(|c| c.eq_ignore_ascii_case(names[0]))
                    && col_types_are_integer.get(idx).copied().unwrap_or(false)
                {
                    rowid_alias_index = Some(idx);
                }
            }
        }

        Ok(ParsedTable {
            columns,
            rowid_alias_index: if without_rowid {
                None
            } else {
                rowid_alias_index
            },
            without_rowid,
            real_affinity,
        })
    }

    fn profile_table(
        file: &mut fs::File,
        header: &DbHeader,
        entry: &SchemaEntry,
        nrows: Option<usize>,
        n_samples: usize,
        path: &Path,
    ) -> Result<Vec<ColumnProfile>> {
        let parsed = parse_create_table(&entry.sql)?;
        if parsed.without_rowid {
            bail!("uses WITHOUT ROWID storage, which isn't supported");
        }

        let n_cols = parsed.columns.len();
        let mut raw: Vec<Vec<Option<String>>> = vec![Vec::new(); n_cols];
        let mut kind_counts: Vec<SqlKindCounts> = vec![SqlKindCounts::default(); n_cols];

        // Decodes and folds each row straight into the per-column
        // accumulators as the b-tree walk visits it, rather than
        // collecting every row's raw payload into a Vec first - the same
        // "fold into per-column storage as records arrive" shape
        // `CsvColumnAccumulator` already uses for CSV, applied here to a
        // b-tree walk instead of a byte stream.
        let mut count = 0usize;
        let mut on_row = |rowid: i64, payload: Vec<u8>| -> Result<()> {
            let values = decode_record(&payload)?;
            for i in 0..n_cols {
                // A record can legitimately have fewer values than the
                // table's current column count (rows written before a
                // later `ALTER TABLE ADD COLUMN`) - treated as NULL for
                // that column, the same graceful-degradation choice every
                // other reader in this project makes for a short row.
                let value = values.get(i).cloned().unwrap_or(Value::Null);
                let value = if Some(i) == parsed.rowid_alias_index && matches!(value, Value::Null) {
                    Value::Integer(rowid)
                } else {
                    value
                };
                let value = apply_affinity(value, parsed.real_affinity[i]);
                raw[i].push(value_to_string(&value, &mut kind_counts[i]));
            }
            Ok(())
        };
        collect_table_rows(
            file,
            entry.rootpage,
            header.page_size,
            header.usable_size,
            path,
            0,
            nrows,
            &mut count,
            &mut on_row,
        )
        .with_context(|| format!("failed reading rows for table '{}'", entry.name))?;

        let mut profiles = Vec::new();
        for (i, name) in parsed.columns.into_iter().enumerate() {
            let total = raw[i].len();
            let non_null: Vec<String> = std::mem::take(&mut raw[i]).into_iter().flatten().collect();
            let current_type = if kind_counts[i].is_empty() {
                "null".to_string()
            } else {
                describe_sql_kinds(&kind_counts[i])
            };
            let col = ColumnInput {
                name,
                current_type,
                raw_values: non_null,
                total,
                skip_heuristics: false,
            };
            profiles.push(profile_column(col, n_samples));
        }
        Ok(profiles)
    }

    /// The SQLite row-source for `render_sql_inline_flat`'s `--sql-mode
    /// inline` second pass, one table at a time - reuses `read_schema`/
    /// `parse_create_table`/`collect_table_rows`/`apply_affinity`/
    /// `value_to_string` directly, the same pieces `profile_table` itself
    /// already builds on, just folding each decoded row into `sink.accept`
    /// instead of a per-column accumulator. `value_to_string` still wants
    /// a `&mut SqlKindCounts` to tally into - a throwaway scratch
    /// accumulator that's never read back, since this row-source only
    /// needs each value's own string form, not a `current_type` summary.
    ///
    /// A `WITHOUT ROWID` table gets the identical disclosed error
    /// `profile_table` already gives (checked the same way, before
    /// `collect_table_rows` is ever called) rather than a guess - the
    /// same "no honest literal to emit" boundary ORC's own compound-
    /// column check already draws for a different reason. `collect_
    /// table_rows` already bounds real page reads via its own `limit`
    /// parameter (the same real-I/O-bounding shape Stata/SAS7BDAT/SPSS's
    /// own row-sources already have), so `nrows` threads straight
    /// through unchanged. SQLite has no header row and no `--skip-rows`
    /// concept, so `sink.has_header` must already be `false`.
    pub(crate) fn stream_sqlite_table_rows_for_sql(
        path: &Path,
        table_name: &str,
        nrows: Option<usize>,
        sink: &mut InlineRowSink<'_>,
    ) -> Result<()> {
        check_no_pending_wal(path)?;
        let mut file = fs::File::open(path).with_context(|| format!("failed to open {path:?}"))?;
        let mut header_buf = [0u8; 100];
        file.read_exact(&mut header_buf)
            .with_context(|| format!("failed reading the SQLite header in {path:?}"))?;
        let header = read_header(&header_buf, path)?;

        let entries = read_schema(&mut file, &header, path)?;
        let entry = entries
            .iter()
            .find(|e| e.name == table_name)
            .with_context(|| format!("table '{table_name}' not found in {path:?}"))?;

        let parsed = parse_create_table(&entry.sql)?;
        if parsed.without_rowid {
            bail!(
                "--sql-mode inline can't emit real data for SQLite table \"{table_name}\" - it \
                 uses WITHOUT ROWID storage, which isn't supported; use --sql-mode staging instead"
            );
        }

        let n_cols = parsed.columns.len();
        let mut dummy_counts = SqlKindCounts::default();
        let mut count = 0usize;
        let mut on_row = |rowid: i64, payload: Vec<u8>| -> Result<()> {
            let values = decode_record(&payload)?;
            let mut row: Vec<Option<String>> = Vec::with_capacity(n_cols);
            for i in 0..n_cols {
                let value = values.get(i).cloned().unwrap_or(Value::Null);
                let value = if Some(i) == parsed.rowid_alias_index && matches!(value, Value::Null) {
                    Value::Integer(rowid)
                } else {
                    value
                };
                let value = apply_affinity(value, parsed.real_affinity[i]);
                row.push(value_to_string(&value, &mut dummy_counts));
            }
            sink.accept(row)
        };
        collect_table_rows(
            &mut file,
            entry.rootpage,
            header.page_size,
            header.usable_size,
            path,
            0,
            nrows,
            &mut count,
            &mut on_row,
        )
        .with_context(|| format!("failed reading rows for table '{table_name}'"))
    }

    pub(crate) fn columns_from_sqlite(
        path: &Path,
        nrows: Option<usize>,
        n_samples: usize,
    ) -> Result<Vec<(String, Vec<ColumnProfile>)>> {
        check_no_pending_wal(path)?;
        let mut file = fs::File::open(path).with_context(|| format!("failed to open {path:?}"))?;
        // Only the fixed 100-byte file header is ever needed up front -
        // everything past it (the schema, every table's own rows) is
        // read one page at a time via `read_page` as the b-tree walk
        // actually needs it, rather than loading the whole database into
        // memory before a single row is decoded.
        let mut header_buf = [0u8; 100];
        file.read_exact(&mut header_buf)
            .with_context(|| format!("failed reading the SQLite header in {path:?}"))?;
        let header = read_header(&header_buf, path)?;
        if header.text_encoding != 0 && header.text_encoding != 1 {
            bail!(
                "{path:?} uses SQLite text encoding {} (UTF-16), which isn't supported - only UTF-8 databases are",
                header.text_encoding
            );
        }

        let entries = read_schema(&mut file, &header, path)?;
        if entries.is_empty() {
            bail!("no user tables found in {path:?}");
        }

        let mut out = Vec::new();
        for entry in entries {
            let profiles = match profile_table(&mut file, &header, &entry, nrows, n_samples, path) {
                Ok(p) => p,
                Err(e) => vec![ColumnProfile {
                    name: "value".to_string(),
                    current_type: "unknown".to_string(),
                    ideal_type: "String".to_string(),
                    description: String::new(),
                    missing_pct: 0.0,
                    sample_values: Vec::new(),
                    notes: format!("table '{}' could not be profiled: {e}", entry.name),
                    row_count: 0, // unreadable - no real row count is knowable
                    numeric_stats: None,
                }],
            };
            out.push((entry.name, profiles));
        }
        Ok(out)
    }
} // mod sqlite_support

#[cfg(feature = "sqlite")]
fn columns_from_sqlite(
    path: &Path,
    nrows: Option<usize>,
    n_samples: usize,
) -> Result<Vec<(String, Vec<ColumnProfile>)>> {
    sqlite_support::columns_from_sqlite(path, nrows, n_samples)
}

#[cfg(not(feature = "sqlite"))]
fn columns_from_sqlite(
    _path: &Path,
    _nrows: Option<usize>,
    _n_samples: usize,
) -> Result<Vec<(String, Vec<ColumnProfile>)>> {
    bail!(
        "SQLite support isn't compiled in - rebuild with `cargo build --release --features sqlite` (or --features full)"
    )
}

// --- Format detection ---

#[derive(Clone, Copy)]
enum InputFormat {
    Csv,
    Tsv,
    Json,
    Parquet,
    ArrowIpc,
    Avro,
    Xlsx,
    Sqlite,
    MsgPack,
    Toml,
    Yaml,
    Cbor,
    Ini,
    Xml,
    FixedWidth,
    Npy,
    Npz,
    CommonLog,
    CombinedLog,
    Syslog,
    Syslog5424,
    Dbase,
    Stata,
    Sas7bdat,
    Spss,
    Orc,
    Bson,
    Plist,
    Json5,
    Har,
    GeoJson,
    Mbox,
    Vcard,
    Ical,
    Ipynb,
    Pdf,
    /// A Delta Lake table directory (`_delta_log/` present) - detected
    /// directly from the input path being such a directory, never from an
    /// extension or `--format` (a Delta table has no file extension of its
    /// own at all). Never constructed by `detect_format`/passed through
    /// `dispatch_reader` - `run_delta_table` resolves and profiles it
    /// directly, bypassing the single-file pipeline entirely, the same way
    /// `sniff-rs diff`'s own subcommand bypasses the normal `Args` grammar.
    /// Exists as an `InputFormat` variant purely so `render_markdown`/
    /// `render_json`'s already-shared rendering code can report a real,
    /// honest format label instead of a borrowed/misleading one. Only
    /// ever actually constructed by `run_delta_table` under `#[cfg(feature
    /// = "delta")]`, hence the dead-code allowance in every other build
    /// (default, or any single other feature) - the same "genuinely used,
    /// just not in every build" treatment this project already gives a
    /// handful of Parquet/Arrow IPC fields for the identical reason.
    #[allow(dead_code)]
    DeltaTable,
    /// An Apache Iceberg table directory (a `metadata/` subdirectory with
    /// real `*.metadata.json` files present) - `IcebergTable`'s own
    /// sibling in every respect `DeltaTable` already documents above:
    /// detected from directory structure alone, never an extension or
    /// `--format`, never constructed by `detect_format`/`dispatch_reader`,
    /// and only ever actually built by `run_iceberg_table` under
    /// `#[cfg(feature = "iceberg")]`.
    #[allow(dead_code)]
    IcebergTable,
}

impl InputFormat {
    /// The label used for this format everywhere it's shown to a user or a
    /// JSON consumer (the `"format"` field, and the Markdown summary line).
    /// Deliberately kept identical to the primary `--format` value that
    /// selects this variant (see the `--format` parsing match below) so
    /// there's exactly one spelling of each format name in this tool's
    /// entire surface, not two that quietly drift - four variants
    /// (`ArrowIpc`/`FixedWidth`/`CommonLog`/`CombinedLog`) used an
    /// underscore-separated label here that didn't match their own
    /// hyphenated `--format` value at all (`arrow_ipc` vs. the accepted
    /// `--format arrow`; `fixed_width`/`common_log`/`combined_log` vs. the
    /// accepted `--format fixed-width`/`common-log`/`combined-log`) until
    /// this was caught by actually reading real Markdown output rather than
    /// just the code - the same "verify against real output" discipline
    /// this project holds every heuristic to.
    fn as_str(&self) -> &'static str {
        match self {
            InputFormat::Csv => "csv",
            InputFormat::Tsv => "tsv",
            InputFormat::Json => "json",
            InputFormat::Parquet => "parquet",
            InputFormat::ArrowIpc => "arrow",
            InputFormat::Avro => "avro",
            InputFormat::Xlsx => "xlsx",
            InputFormat::Sqlite => "sqlite",
            InputFormat::MsgPack => "msgpack",
            InputFormat::Toml => "toml",
            InputFormat::Yaml => "yaml",
            InputFormat::Cbor => "cbor",
            InputFormat::Ini => "ini",
            InputFormat::Xml => "xml",
            InputFormat::FixedWidth => "fixed-width",
            InputFormat::Npy => "npy",
            InputFormat::Npz => "npz",
            InputFormat::CommonLog => "common-log",
            InputFormat::CombinedLog => "combined-log",
            InputFormat::Syslog => "syslog",
            InputFormat::Syslog5424 => "syslog5424",
            InputFormat::Dbase => "dbase",
            InputFormat::Stata => "stata",
            InputFormat::Sas7bdat => "sas7bdat",
            InputFormat::Spss => "spss",
            InputFormat::Orc => "orc",
            InputFormat::Bson => "bson",
            InputFormat::Plist => "plist",
            InputFormat::Json5 => "json5",
            InputFormat::Har => "har",
            InputFormat::GeoJson => "geojson",
            InputFormat::Mbox => "mbox",
            InputFormat::Vcard => "vcard",
            InputFormat::Ical => "icalendar",
            InputFormat::Ipynb => "ipynb",
            InputFormat::Pdf => "pdf",
            InputFormat::DeltaTable => "delta",
            InputFormat::IcebergTable => "iceberg",
        }
    }
}

// --- The format catalog: one source of truth for --list-formats, the
// --format/extension-detection error messages, and (via a #[cfg(test)]
// guard below) HELP_TEXT itself ---
//
// Prompted directly by an "investigate and plan how to make this CLI as
// agent-friendly as possible" request: the biggest concrete finding was
// that HELP_TEXT's own hand-written prose had drifted out of sync with
// this tool's real format support (missing SPSS/ORC/BSON/plist/JSON5/
// HAR/GeoJSON/vCard/iCalendar/MBOX/Delta/Iceberg from its own opening
// paragraph and --format option line), while the *separate* hand-written
// list backing the `--format bogus` error message had been kept current
// - two independently-maintained lists of the same information, already
// caught disagreeing once and certain to disagree again. `FORMAT_CATALOG`
// is the fix: every format this tool can ever dispatch to gets exactly
// one entry here, and every other place that needs to enumerate formats
// (the two error messages below, `--list-formats`) reads from it instead
// of carrying its own copy.

/// One row of `FORMAT_CATALOG` - see that constant's own doc comment.
struct FormatInfo {
    /// The canonical name: identical to `InputFormat::as_str()`'s own
    /// spelling, and (for anything that isn't `directory`) the exact
    /// `--format` value that selects it.
    name: &'static str,
    /// File extensions this format auto-detects from with no `--format`
    /// needed - empty for a format reachable only via `--format` (fixed-
    /// width text, the four log formats) or only via directory structure
    /// (`directory: true`).
    extensions: &'static [&'static str],
    /// The Cargo feature this format needs, or `None` if it's always
    /// compiled in (csv/tsv/json/jsonl, fixed-width).
    feature: Option<&'static str>,
    /// Whether *this build* actually has that feature compiled in - always
    /// `true` when `feature` is `None`. `cfg!(feature = "...")` evaluates
    /// to a plain `bool` literal at compile time, so this is real,
    /// per-build information, not a static claim about every build.
    compiled_in: bool,
    /// Delta/Iceberg only: detected from directory *structure* (a
    /// `_delta_log/`/`metadata/` subdirectory), never from an extension or
    /// `--format` at all - see `is_delta_table_dir`/`is_iceberg_table_dir`.
    directory: bool,
}

/// Every format this tool can ever dispatch to, one entry each - see this
/// section's own header comment for why this exists. Kept honest against
/// the real `--format` parser two ways: `format_catalog_names_match_the_
/// format_override_parser` (a `#[cfg(test)]` below) round-trips every
/// non-directory entry's `name` through `detect_format`'s own `--format`
/// override branch and checks the resulting `InputFormat::as_str()`
/// matches, and `help_text_mentions_every_catalog_format` checks every
/// entry's `name` appears somewhere in `HELP_TEXT`.
