    fn suggest_ideal_type_recognizes_vin() {
        let (ideal, note) = suggest_ideal_type(&[REFERENCE_VIN], "String");
        assert_eq!(ideal, "VIN");
        assert!(note.contains("Vehicle Identification Number"));
    }

