    fn suggest_ideal_type_recognizes_ulid() {
        let (ideal, note) = suggest_ideal_type(&["01ARZ3NDEKTSV4RRFFQ69G5FAV"], "String");
        assert_eq!(ideal, "ULID");
        assert!(note.contains("ULID"));
    }

