    #[test]
    fn sql_literal_for_value_quotes_a_non_finite_float_instead_of_a_bare_token() {
        // Regression test for a real bug found by piping generated SQL
        // into a real sqlite3 build: a bare, unquoted `inf`/`-inf`/`nan`
        // token is not valid SQL numeric-literal syntax at all - SQLite
        // parses it as an unquoted identifier and fails outright ("no
        // such column: inf"). Falling back to a quoted string keeps the
        // script syntactically valid on every engine.
        // "nan" is deliberately not tested here - it's already one of
        // this project's own MISSING_SENTINELS tokens (matching pandas'
        // own default), so it resolves to NULL before ever reaching the
        // f64 branch at all, the same as it's excluded from typing
        // entirely in the real CSV reader's own Pass 1.
        assert_eq!(sql_literal_for_value("Infinity", "f64"), "'Infinity'");
        assert_eq!(sql_literal_for_value("-inf", "f64"), "'-inf'");
        // An ordinary finite float is untouched (still unquoted).
        assert_eq!(sql_literal_for_value("120.50", "f64"), "120.50");
    }

    #[test]
    fn sql_string_literal_strips_an_embedded_nul_byte() {
        // Regression test for a real bug found the same way: a genuine
        // NUL byte embedded in a value corrupted the rest of a real
        // sqlite3 CLI run when piped straight into it - a property of a
        // .sql script being plain text, not an engine-specific quirk.
        assert_eq!(sql_string_literal("Alice\0"), "'Alice'");
        assert_eq!(sql_string_literal("a\0b\0c"), "'abc'");
    }

    #[test]
    fn sql_unique_column_names_disambiguates_a_duplicate_or_blank_header() {
        let profiles = |names: &[&str]| -> Vec<ColumnProfile> {
            names
                .iter()
                .map(|n| ColumnProfile {
                    name: n.to_string(),
                    current_type: "String".to_string(),
                    ideal_type: "String".to_string(),
                    description: String::new(),
                    missing_pct: 0.0,
                    sample_values: vec![],
                    notes: String::new(),
                    row_count: 1,
                    numeric_stats: None,
                })
                .collect()
        };
        // Regression test for a real bug found by piping generated SQL
        // into a real sqlite3 build: a repeated CSV header column
        // ("id,name,name,age") produced two identically-named columns in
        // one CREATE TABLE - "duplicate column name: name".
        assert_eq!(
            sql_unique_column_names(&profiles(&["id", "name", "name", "age"])),
            vec!["id", "name", "name_2", "age"]
        );
        // A blank header cell (found via a real preamble-detection
        // fixture) gets a real, non-empty placeholder name instead of an
        // empty SQL identifier.
        assert_eq!(
            sql_unique_column_names(&profiles(&["a", "", ""])),
            vec!["a", "column", "column_2"]
        );
    }

    #[test]
    fn sql_literal_for_value_decodes_a_base_prefixed_int_literal_to_decimal() {
        // Regression test for a real bug found by eyeballing generated
        // SQL against a real `hex_value` column: ideal_type "i64" doesn't
        // always mean the raw text is already a plain ANSI decimal
        // numeral - parse_prefixed_int is the one grammar check that
        // resolves to "i64" from a "0x"/"0b"/"0o"-prefixed literal, which
        // isn't a numeric literal every SQL engine accepts unquoted.
        assert_eq!(sql_literal_for_value("0x1A", "i64"), "26");
        assert_eq!(sql_literal_for_value("0xFF", "i64"), "255");
        assert_eq!(sql_literal_for_value("0b1010", "i64"), "10");
        assert_eq!(sql_literal_for_value("0o17", "i64"), "15");
        // An ordinary plain decimal integer is untouched.
        assert_eq!(sql_literal_for_value("42", "i64"), "42");
    }

