    fn sql_literal_for_value_strips_currency_and_thousands_separators() {
        assert_eq!(sql_literal_for_value("$1,234.56", "f64"), "1234.56");
        assert_eq!(sql_literal_for_value("(45.00)", "f64"), "-45.00");
    }

